import type { GameState, Milestone, Track } from '../engine/types';

// THE REFORM LIBRARY, SECOND EDITION
// Reforms are policy generations, not a list to finish. Each track has its
// foundations (in order, or any order on a loose track); once they are delivered
// the deepening opens; and some problems appear only because of what an earlier
// government did, and only while they exist. Some reforms are rival answers to
// the same question: choosing one closes the other, and neither is the right one.
// Some can be undone by a President for a gain now; the next one inherits the
// damage and can restore them. Programmes that exist in some form at the start
// are on the statute book: the work is doing them properly.
// Names of laws and programmes are invented.

const SENATE = { needs: { v: ['senate', '>=', 50] as [string, '>=', number] }, needsText: 'You do not have the Senate. Win over your senators first.' };
const AMEND = { needs: { v: ['senate', '>=', 56] as [string, '>=', number] }, needsText: 'It changes the constitution: two thirds of the Senate and the state assemblies. Your senators and governors must be firmly with you.' };

const done = (s: GameState, id: string) => s.agenda.done.includes(id);
const openCases = (s: GameState) => (s.cases ?? []).filter((c) => !c.outcome).length;

