// ------------------------------------------------------------ helpers for writing reforms compactly
type M = Milestone;
const g2 = (m: Omit<M, 'gen'>): M => ({ ...m, gen: 2 });
const g3 = (m: Omit<M, 'gen'>): M => ({ ...m, gen: 3 });

